NAME = 'ACV: A Conservative Version'
BOOK = 'Philippians'

CHAPTERS = {
    1: {
        1: 'Pavel in Timotej, hlapca Kristusa Jezusa, vsem svetim v Kristusu Jezusu, ki bivajo v Filipih, s škofi in diakoni:',
        2: 'Milost vam in mir od Boga Očeta našega in Gospoda Jezusa Kristusa!',
        3: 'Zahvaljujem se Bogu svojemu, kadarkoli se vas spominjam,',
        4: 'vedno v sleherni molitvi za vas vse, ko opravljam molitev z veseljem,',
        5: 'da ste se udeleževali širjenja evangelija od prvega do današnjega dne,',
        6: 'ker sem prepričan prav o tem, da on, ki je začel v vas dobro delo, ga dokonča do dne Jezusa Kristusa;',
        7: 'kakor je tudi meni spodobno, misliti to za vas vse, ker vas imam v srcu svojem kot take, ki ste vsi i v sponah mojih i v zagovarjanju in utrjevanju evangelija sodeležniki milosti z menoj.',
        8: 'Kajti priča mi je Bog, kako hrepenim po vas vseh v srčni ljubezni Kristusa Jezusa.',
        9: 'In za to molim, da naj ljubezen vaša še bolj in bolj raste v spoznanju in slehernem razumu,',
        10: 'da presojate, kaj je boljše in kaj ne; da bodete čisti in brez spotikljaja za dan Kristusov,',
        11: 'napolnjeni s sadom pravičnosti, ki se množi po Jezusu Kristusu, v slavo in hvalo Bogu.',
        12: 'Želim pa, da spoznate, bratje, da je pripomoglo še bolj v prospeh evangeliju to, kar me je zadelo,',
        13: 'tako da so spone moje postale očitne, da so za Kristusa, vsej cesarski straži in vsem drugim,',
        14: 'in da si večina bratov, v Gospodu dobivši zaupanje po mojih sponah, upa bolj brez strahu govoriti besedo Božjo.',
        15: 'Nekateri sicer oznanjajo Kristusa tudi iz zavisti in prepirljivosti, nekateri pa tudi iz dobre volje.',
        16: 'Ti, ki to delajo iz ljubezni, vedo, da sem postavljen v zagovarjanje evangelija;',
        17: 'drugi pa oznanjajo Kristusa iz strankarstva, ne iz čistega namena, ker menijo, da mi povzročijo stisko v sponah mojih.',
        18: 'Ali kaj na tem? Saj se tako ali tako, bodisi s pretvezo, bodisi v resnici oznanja Kristus, in tega se veselim, da, bom se še veselil.',
        19: 'Vem namreč, da mi to posluži v rešitev po prošnji vaši in podpori Duha Jezusa Kristusa,',
        20: 'po trdnem pričakovanju in upanju mojem, da ne bom v ničemer osramočen, marveč da se bo v vsej srčnosti pričevanja kakor vedno, tudi sedaj poveličeval Kristus v mojem telesu, bodisi z življenjem ali s smrtjo.',
        21: 'Zakaj meni je življenje Kristus, in smrt dobiček.',
        22: 'Ako pa mi je še živeti v mesu, to mi pomnoži sad dela; in kaj naj izvolim, ne vem.',
        23: 'Pritiska me pa oboje: želja me je, ločiti se in biti s Kristusom, zakaj to je veliko, veliko boljše;',
        24: 'toda ostati v mesu je potrebnejše za vas.',
        25: 'In v tem zaupanju vem, da ostanem in z vami vsemi ostanem za vaš prospeh in veselje v veri,',
        26: 'da bode hvala vaša preobila v Kristusu Jezusu zaradi mene, vsled zopetnega prihoda mojega k vam.',
        27: 'Samo naj bode življenje vaše, kakor se spodobi evangeliju Kristusovemu, da bom vedel, bodisi da pridem in vas vidim, bodisi da v daljavi slišim, kako je pri vas, da stojite trdno v enem duhu, enodušno in skupno se boreč za vero evangelija,',
        28: 'in da vas nikakor ne morejo zastrašiti nasprotniki; kar je njim očitno znamenje pogube, vam pa zveličanja, in to od Boga;',
        29: 'ker vam je iz milosti dano za Kristusa, da ne samo verujete vanj, ampak tudi zanj trpite,',
        30: 'imajoč isti boj, ki ste ga videli na meni in zdaj slišite o meni.',
    },
    2: {
        1: 'Če je torej pri vas kako izpodbujanje v Kristusu, če je kaka tolažba ljubezni, če kaka sodeležnost Duha, če kako usmiljenje in milovanje:',
        2: 'napolnite mi veselje s tem, da ste složni, da imate eno ljubezen, enodušno ravnate, za eno skrbite;',
        3: 'ničesar ne delajte iz sebičnosti ali praznega slavoljubja, temuč po ponižnosti cenite drug drugega više od sebe.',
        4: 'Ne glejte vsak na svoje, ampak vsak tudi na to, kar je drugega.',
        5: 'To mišljenje bodi v vas, ki je bilo v Kristusu Jezusu:',
        6: 'kateri, ko je bil v podobi Božji, ni štel za rop biti enak Bogu,',
        7: 'temuč samega sebe je izpraznil in je nase vzel podobo hlapca in postal enak človeku; in po zunanjosti spoznan za človeka,',
        8: 'se je ponižal in je bil pokoren do smrti, smrti pa na križu.',
        9: 'Zato ga je tudi Bog visoko povišal in mu podelil ime, ki je nad vsako ime;',
        10: 'da se naj v imenu Jezusa pripogiblje vsako koleno teh, ki so v nebesih in na zemlji in pod zemljo,',
        11: 'in vsak jezik pripoznava, da Jezus Kristus je Gospod, v slavo Boga Očeta.',
        12: 'Zatorej, ljubljeni moji, kakor ste bili vsekdar poslušni, ne samo v pričujočnosti moji, temuč mnogo bolj sedaj v nepričujočnosti moji, v strahu in trepetu vršite zveličanje svoje;',
        13: 'Bog namreč je, ki dela v vas i voljo i delovanje, po svoji dobri volji.',
        14: 'Vse delajte brez godrnjanja in pomišljanja,',
        15: 'da bodete brez pogreška in čisti, otroci Božji brez madeža sredi sključenega in spačenega rodú, med katerimi se svetite kakor nebeške luči na svetu',
        16: 'in jim predstavljate besedo življenja; da imam hvalo za dan Kristusov, da nisem zastonj tekal in ne trudil se zastonj.',
        17: 'Ali ko bi bil tudi darovan nad daritvijo in službo vere vaše, veselim se in z vami vsemi vred se veselim.',
        18: 'Enako pa se veselite tudi vi in veselite se z menoj vred!',
        19: 'Upam pa v Gospoda Jezusa, da vam skoraj pošljem Timoteja, da bodem tudi jaz mirnega srca, ko zvem, kako je pri vas.',
        20: 'Nikogar namreč nimam enakega mišljenja, ki bo pošteno skrbel za vaše zadeve;',
        21: 'zakaj vsi iščejo svojega, ne kar je Kristusa Jezusa.',
        22: 'Preizkušenost pa poznate njegovo, da je, kakor otrok z očetom, z menoj služil za širjenje evangelija.',
        23: 'Tega torej upam poslati, precej ko izprevidim, kako bo z menoj.',
        24: 'Trdno se pa nadejam v Gospodu, da tudi sam pridem skoraj.',
        25: 'Potrebno se mi je pa zdelo poslati k vam Epafrodita, brata in sodelavca in sovojaka mojega, vašega pa poslanca in služabnika potrebe moje;',
        26: 'kajti hrepenel je po vas vseh in se žalostil, ker ste slišali, da je zbolel.',
        27: 'In res, da je zbolel in je bil blizu smrti; ali Bog se ga je usmilil, a ne samo njega, ampak tudi mene, da ne bi imel žalosti nad žalost.',
        28: 'Tem hitreje torej sem ga poslal, da ga vidite ter se veselite in da bodem jaz manj žalosten.',
        29: 'Sprejmite ga torej v Gospodu z vsem veseljem, in take imejte v čislih;',
        30: 'kajti zaradi dela Kristusovega se je bil približal smrti, vnemar pustivši življenje, da bi nadomestil, s čimer mi vi niste mogli poslužiti.',
    },
    3: {
        1: 'Sicer pa, bratje moji, veselite se v Gospodu! Eno in isto vam pisati ni sitno meni, vam pa je v potrjenje.',
        2: 'Pazite se psov, pazite se slabih delavcev, pazite se razreze!',
        3: 'Kajti mi smo obreza, ki v Božjem Duhu služimo Bogu in se hvalimo v Kristusu Jezusu in ne stavimo upanja v meso,',
        4: 'dasi imam jaz lahko tudi v meso zaupanje. Če meni kdo drugi zaupati v meso, jaz tem bolj:',
        5: 'obrezan osmi dan, iz rodu Izraelovega, rodovine Benjaminove, Hebrejec iz Hebrejcev, po postavi farizej,',
        6: 'po gorečnosti preganjalec cerkve, po pravičnosti, ki sloni na postavi, brez pogreška.',
        7: 'Ali kar mi je bilo dobiček, to sem imel zaradi Kristusa za izgubo.',
        8: 'Ali zares, tudi zdaj imam vse za izgubo, ker je mnogo boljše spoznanje Kristusa Jezusa, Gospoda mojega, zaradi katerega sem vse izgubil in imam to za smeti, da pridobim Kristusa',
        9: 'in se najdem v njem, ne imajoč svoje pravičnosti, ki izvira iz postave, ampak tiste, ki je po veri v Kristusa, iz Boga pravičnosti, na podlagi vere,',
        10: 'da spoznam njega in moč vstajenja njegovega in sodeleštvo njegovega trpljenja, ko sem njegovi smrti podoben,',
        11: 'da kako dospem do vstajenja izmed mrtvih.',
        12: 'Ne da sem že dosegel ali da sem že dovršen, a ženem se, da kako dosežem, za kar sem bil tudi dosežen od Kristusa Jezusa.',
        13: 'Bratje, jaz ne mislim sam zase, da sem že dosegel; eno pa delam: pozabivši, kar je zadaj, a vzpenjajoč se po tem, kar je spredaj,',
        14: 'hitim proti cilju za darilom nebeškega poklica Božjega v Kristusu Jezusu.',
        15: 'Kolikor nas je torej popolnih, bodimo teh misli; in če ste v čem drugih misli, tudi to vam razodene Bog.',
        16: 'Toda do česar smo dospeli, po tem stopajmo naprej!',
        17: 'Posnemalci moji bodite, bratje, in glejte na one, ki tako žive, kakor imate nas za zgled.',
        18: 'Zakaj veliko jih živi, ki sem jih vam mnogokrat imenoval, zdaj pa jih tudi jokajoč imenujem sovražnike križa Kristusovega,',
        19: 'katerih konec poguba, katerih Bog trebuh in njih slava v njih sramoti, ki jim je zemeljsko v mislih.',
        20: 'Kajti naša domovna država je v nebesih, odkoder tudi pričakujemo Zveličarja, Gospoda Jezusa Kristusa,',
        21: 'ki preobrazi telo ponižanja našega, da bode podobno telesu slave njegove, po moči, s katero si more tudi vse podvreči.',
    },
    4: {
        1: 'Zatorej, bratje moji ljubljeni in zaželjeni, veselje in venec moj, tako stojte trdno v Gospodu, ljubljeni!',
        2: 'Evodijo opominjam in Sintiho opominjam, da bodita enih misli v Gospodu.',
        3: 'In prosim tudi tebe, moj tovariš zvesti, pomagaj jima, ki sta se z menoj borili v evangeliju, tudi s Klementom in drugimi sodelavci mojimi, katerih imena so v knjigi življenja.',
        4: 'Veselite se vedno v Gospodu! še enkrat pravim: Veselite se!',
        5: 'Krotkost vaša bodi znana vsem ljudem. Gospod je blizu.',
        6: 'Nič ne skrbite, temuč v vsem naj se Bogu naznanjajo želje vaše v molitvi in prošnji z zahvaljevanjem.',
        7: 'In mir Božji, ki presega ves razum, bo čuval in ohranil srca vaša in misli vaše v Kristusu Jezusu.',
        8: 'Sicer pa, bratje, kar je resnično, kar čestito, kar pravično, kar čisto, kar ljubeznivo, kar sloveče, če je kaka čednost in če kaka hvala, to premišljajte.',
        9: 'Kar ste se tudi naučili in prejeli in slišali in videli na meni, to delajte, in Bog miru bode z vami.',
        10: 'Razveselil sem se pa silno v Gospodu, da je končno zopet ozelenela vaša skrb zame; na to ste sicer tudi mislili, a prilike niste imeli.',
        11: 'Ne da bi dejal to zaradi pomanjkanja; jaz sem se namreč naučil, zadovoljen biti s tem, kar imam.',
        12: 'Znam se tudi ponižati, znam tudi v obilosti živeti; sleherne in vsake stvari sem vajen, sit biti in lačen, v obilosti živeti in v pomanjkanju.',
        13: 'Vse morem v njem, ki me krepča, v Kristusu.',
        14: 'Vendar ste prav storili, da ste pokazali sočutje z mojo stisko.',
        15: 'Veste pa tudi sami, Filipljani, da se v začetku širjenja evangelija, ko sem odšel iz Macedonije, ni udeležila nobena cerkev z menoj na račun dajanja in prejemanja, razen vas samih;',
        16: 'saj tudi v Solun ste mi poslali enkrat in dvakrat za potrebo.',
        17: 'Ne da bi iskal daru, marveč sadu iščem, ki naj se množi vam na račun.',
        18: 'Imam pa vsega dovolj in preobilo; napolnjen sem, dobivši od Epafrodita vaše dari, sladko dišavo, prijetno daritev, Bogu po volji.',
        19: 'Bog moj pa napolni vsako potrebo vašo po bogastvu svojem v slavi v Kristusu Jezusu.',
        20: 'Bogu pa in Očetu našemu slava na vekov veke! Amen.',
        21: 'Pozdravite vsakega svetega v Kristusu Jezusu. Pozdravljajo vas bratje, ki so z menoj.',
        22: 'Pozdravljajo vas vsi sveti, posebno pa oni iz cesarjeve hiše.',
        23: 'Milost Gospoda Jezusa Kristusa z duhom vašim!',
    },
}
